import React from "react";
import { clsx } from "clsx";

import { MainNavClasses } from "../main-nav.styles";
import { useMainNav } from "../hooks/use-main-nav";

export const MainNavHeader: React.FC<
  React.PropsWithChildren<{ className?: string; style?: React.CSSProperties }>
> = ({ className, style, children, ...props }) => {
  const { dataMainNavState } = useMainNav();
  return (
    <div
      className={clsx(MainNavClasses.header, className)}
      data-main-nav-state={dataMainNavState}
      style={style}
      {...props}
    >
      {children}
    </div>
  );
};
MainNavHeader.displayName = "MainNav.Header";

export const MainNavContent: React.FC<
  React.PropsWithChildren<{ className?: string; style?: React.CSSProperties }>
> = ({ className, style, children, ...props }) => {
  const { dataMainNavState, contentRef } = useMainNav();
  return (
    <div
      ref={contentRef}
      className={clsx(MainNavClasses.content, className)}
      data-main-nav-state={dataMainNavState}
      style={style}
      {...props}
    >
      {children}
    </div>
  );
};
MainNavContent.displayName = "MainNav.Content";

export const MainNavFooter: React.FC<
  React.PropsWithChildren<{ className?: string; style?: React.CSSProperties }>
> = ({ className, style, children, ...props }) => {
  const { dataMainNavState } = useMainNav();
  return (
    <div
      className={clsx(MainNavClasses.footer, className)}
      data-main-nav-state={dataMainNavState}
      style={style}
      {...props}
    >
      {children}
    </div>
  );
};
MainNavFooter.displayName = "MainNav.Footer";
